using System;
using System.Collections.Generic;
using GrimDynasty.ReverseClient.Actions;

// Pure-memory tests of the recovered pointer-vector helpers and their actual
// GetGroup/Join callers. Successful BCL allocations are an explicit own domain;
// no native allocator, heap-failure/EH, loaded crowd or movement is simulated.
public static class NavigationCrowdGrowthTests {
 static int scenarios,assertions;
 public static int Scenarios{get{return scenarios;}}
 public static int Assertions{get{return assertions;}}
 static void Check(bool value,string why){assertions++;if(!value)throw new Exception(why);}
 static void Equal<T>(T expected,T actual,string why){Check(EqualityComparer<T>.Default.Equals(expected,actual),why+" expected="+expected+" actual="+actual);}
 static void Same(object expected,object actual,string why){Check(Object.ReferenceEquals(expected,actual),why);}
 static void Test(string name,Action body){body();scenarios++;Console.WriteLine("PASS "+name);}
 static void Missing(uint at,Action body,string why){try{body();}catch(MissingContract e){Equal(at,e.Address,why+" address");return;}throw new Exception("Expected explicit own stop: "+why);}
 static void Unknown<T>(Field<T> field,string why){Missing(0,delegate{field.Read(0);},why);}
 static NavigationCrowdPointerVector<T> Empty<T>()where T:class{var v=new NavigationCrowdPointerVector<T>();v.Begin00.Write(null);v.End08.Write(null);v.Capacity10.Write(null);return v;}
 static NavigationCrowdPointerVector<T> Vector<T>(int capacity,int count)where T:class{var v=new NavigationCrowdPointerVector<T>();v.InstallOwnStorage(new NavigationCrowdPointerBuffer<T>(capacity),count);return v;}
 static NavigationCrowdPointerBuffer<T> Buffer<T>(NavigationCrowdPointerVector<T> v)where T:class{return v.Begin00.Read(0).Buffer;}
 static void Int3(NavigationCrowdInt3 p,int x,int y,int z){p.X.Write(x);p.Y.Write(y);p.Z.Write(z);}
 static NavigationCrowdAgent Agent(){var a=new NavigationCrowdAgent();a.Position48.X.Write(0.25f);a.Position48.Y.Write(0.5f);a.Position48.Z.Write(0.25f);a.Radius10.Write(0.25f);a.Height14.Write(1);return a;}
 public static void Run(){
  scenarios=0;assertions=0;
  Test("Null pointer triple grows to actual fresh storage without initializing spare payload",delegate{
   var v=Empty<object>();var i=new Invocation();NavigationCrowdStateContracts.Reallocate034FE0(v,2,i);var fresh=Buffer(v);
   Same(fresh,v.LastGrowthAllocation,"Diagnostic identifies the actual allocation");Equal(2,fresh.Cells.Length,"Requested absolute capacity");Equal(0,v.Begin00.Read(0).Index,"New begin");Equal(0,v.End08.Read(0).Index,"Empty size retained");Equal(2,v.Capacity10.Read(0).Index,"Capacity published");Same(fresh,v.End08.Read(0).Buffer,"End shares new allocation");Same(fresh,v.Capacity10.Read(0).Buffer,"Capacity shares new allocation");Unknown(fresh.At(0,0),"First unused pointer has no invented null");Unknown(fresh.At(1,0),"Second unused pointer has no invented null");Equal(0x3506du,i.At,"Normal helper return reached");
  });
  Test("Copy keeps duplicate pointee identity known null and unknown bits while releasing only old storage",delegate{
   var v=Vector<NavigationCrowdAgent>(5,4);var old=Buffer(v);var shared=new NavigationCrowdAgent();var spare=new NavigationCrowdAgent();old.At(0,0).Write(shared);old.At(1,0).Write(shared);old.At(2,0).Write(null);old.At(4,0).Write(spare);var oldCell=old.Cells[0];var snapshot=oldCell.Snapshot();
   NavigationCrowdStateContracts.Reallocate034FE0(v,9,new Invocation());var fresh=Buffer(v);
   Check(!Object.ReferenceEquals(old,fresh),"Backing identity changes");Equal(4,v.End08.Read(0).Index,"Only logical size copied");Equal(9,v.Capacity10.Read(0).Index,"Direct helper uses exact requested capacity");Same(shared,fresh.At(0,0).Read(0),"First pointee identity");Same(shared,fresh.At(1,0).Read(0),"Duplicate identity is preserved");Same(null,fresh.At(2,0).Read(0),"Known-null pointer remains known null");Unknown(fresh.At(3,0),"Unknown pointer payload copied without rejection");Unknown(fresh.At(4,0),"Old spare content is not copied");Unknown(fresh.At(8,0),"New tail is not cleared");Check(!Object.ReferenceEquals(oldCell,fresh.At(0,0)),"Copy creates independent cell storage");Missing(0,delegate{old.At(0,0);},"Old address is invalid after release");shared.RequireLive(0);spare.RequireLive(0);Same(shared,snapshot.Read(0),"Retained snapshot is a value not a released address");fresh.At(0,0).Write(null);Same(shared,fresh.At(1,0).Read(0),"Copied duplicate cells do not alias each other");Same(shared,snapshot.Read(0),"Changing new storage does not change prior snapshot");
  });
  Test("Additional reserve chooses max required size and one-and-a-half capacity",delegate{
   var v=Vector<object>(4,4);var old=Buffer(v);NavigationCrowdStateContracts.ReserveAdditional034EC0(v,1,new Invocation());var six=Buffer(v);Equal(6,v.Capacity10.Read(0).Index,"Four full slots grow to six");Equal(4,v.End08.Read(0).Index,"Reserve does not append");Missing(0,delegate{old.At(0,0);},"Prior allocation released");Unknown(six.At(0,0),"Unobserved existing payload remains unobserved");
   NavigationCrowdStateContracts.ReserveAdditional034EC0(v,3,new Invocation());Equal(9,v.Capacity10.Read(0).Index,"Six capacity grows to nine although only seven required");Equal(4,v.End08.Read(0).Index,"Logical size still four");Missing(0,delegate{six.At(0,0);},"Second previous allocation released");
   var large=Vector<object>(4,4);NavigationCrowdStateContracts.ReserveAdditional034EC0(large,9,new Invocation());Equal(13,large.Capacity10.Read(0).Index,"Required size wins when larger than policy");var one=Vector<object>(1,1);NavigationCrowdStateContracts.ReserveAdditional034EC0(one,1,new Invocation());Equal(2,one.Capacity10.Read(0).Index,"One plus shifted half cannot undersize requirement");
  });
  Test("Sufficient spare capacity returns before consuming unknown begin",delegate{
   var v=Vector<object>(4,2);var old=Buffer(v);var end=v.End08.Read(0);var cap=v.Capacity10.Read(0);v.Begin00.Forget();var i=new Invocation();NavigationCrowdStateContracts.ReserveAdditional034EC0(v,2,i);
   Unknown(v.Begin00,"Early return does not demand begin");Same(end,v.End08.Read(0),"End address unchanged");Same(cap,v.Capacity10.Read(0),"Capacity address unchanged");Same(null,v.LastGrowthAllocation,"No allocation happened");old.RequireLive(0);Equal(0x34f41u,i.At,"Native no-growth return");
  });
  Test("Late unknown capacity retains copied fresh local and leaves old header and lifetime intact",delegate{
   var v=Vector<object>(3,2);var old=Buffer(v);var value=new object();old.At(0,0).Write(value);var begin=v.Begin00.Read(0);var end=v.End08.Read(0);v.Capacity10.Forget();
   Missing(0x3503a,delegate{NavigationCrowdStateContracts.Reallocate034FE0(v,5,new Invocation());},"Capacity consumed only after real copy");var fresh=v.LastGrowthAllocation;Check(fresh!=null,"Fresh local retained diagnostically");Same(value,fresh.At(0,0).Read(0),"Completed copy retained before free-size read");Unknown(fresh.At(1,0),"Unknown payload copy also completed");Unknown(fresh.At(2,0),"Unused new memory remains unknown");Same(begin,v.Begin00.Read(0),"Begin not published");Same(end,v.End08.Read(0),"End not published");Unknown(v.Capacity10,"Unknown capacity not replaced");Same(value,old.At(0,0).Read(0),"Original allocation still live because free was not reached");
   // An explicitly malformed extent is an OWN rejection, not a native return.
   var invalid=Vector<object>(3,2);var original=Buffer(invalid);var marker=new object();original.At(0,0).Write(marker);invalid.Capacity10.Write(new NavigationCrowdPointerAddress<object>(original,2));Missing(0x35041,delegate{NavigationCrowdStateContracts.Reallocate034FE0(invalid,4,new Invocation());},"Free requires complete declared allocation");Same(marker,invalid.LastGrowthAllocation.At(0,0).Read(0),"Copy precedes rejected free extent");Same(original,Buffer(invalid),"No new begin published on rejected free");Same(marker,original.At(0,0).Read(0),"Rejected free does not invalidate old allocation");
  });
  Test("Unsupported allocator and memory spans stop without claiming native allocation failure",delegate{
   var v=Empty<object>();Missing(0x35002,delegate{NavigationCrowdStateContracts.Reallocate034FE0(v,0,new Invocation());},"Zero allocator contract remains unknown");Same(null,v.LastGrowthAllocation,"Zero request does not fabricate allocation");Missing(0x35002,delegate{NavigationCrowdStateContracts.Reallocate034FE0(v,2147483648ul,new Invocation());},"Outside bounded managed allocation domain");Same(null,v.Begin00.Read(0),"Null begin retained");Same(null,v.End08.Read(0),"Null end retained");Same(null,v.Capacity10.Read(0),"Null capacity retained");
   var shortDestination=Vector<object>(2,2);var old=Buffer(shortDestination);old.At(0,0).Write(new object());Missing(0x35017,delegate{NavigationCrowdStateContracts.Reallocate034FE0(shortDestination,1,new Invocation());},"Copy span exceeds actual new destination extent");Equal(1,shortDestination.LastGrowthAllocation.Cells.Length,"Fresh local exists before rejected copy");Unknown(shortDestination.LastGrowthAllocation.At(0,0),"No partial fake copy before span check");Same(old,Buffer(shortDestination),"Old header retained");old.RequireLive(0);
   var released=Vector<object>(2,1);var dead=Buffer(released);dead.MarkReleased();Missing(0x35017,delegate{NavigationCrowdStateContracts.Reallocate034FE0(released,4,new Invocation());},"Source address checked at copy consumption");Check(released.LastGrowthAllocation!=null,"Allocation preceded rejected source read");Same(dead,Buffer(released),"Released source header is not silently repaired");Unknown(released.LastGrowthAllocation.At(0,0),"No invented payload after source failure");
  });
  Test("Actual GetGroup and Join grow null vectors preserve shared members and expose post-append failure",delegate{
   var manager=new NavigationCrowdManager();manager.Groups10.Begin00.Write(null);manager.Groups10.End08.Write(null);manager.Groups10.Capacity10.Write(null);manager.MaxGroups0C.Write(1);Int3(manager.Margin00,0,0,0);var lower=new NavigationCrowdInt3();var upper=new NavigationCrowdInt3();Int3(lower,-2,0,-2);Int3(upper,2,2,2);var b=new NavigationCrowdStateBoundaries(null);b.DisableGroupAssert422B90.Write(0);b.UseObservedGroupConstants();
   var group=NavigationCrowdStateContracts.GetGroup25A250(manager,lower,upper,b,new Invocation());Same(manager,group.Owner00.Read(0),"Actual constructor owner");Same(group,Buffer(manager.Groups10).At(0,0).Read(0),"Actual group published after growth");Equal(1,manager.Groups10.End08.Read(0).Index,"Group count one");Equal(1,manager.Groups10.Capacity10.Read(0).Index,"Null groups grew to one");Unknown(group.Query08,"Unknown query pointer was copied rather than defaulted");Same(null,group.Members28.Begin00.Read(0),"Native constructor left member vector null");
   var agent=Agent();NavigationCrowdStateContracts.Join25C340(group,agent,b,new Invocation());var first=Buffer(group.Members28);Same(agent,first.At(0,0).Read(0),"First actual member append");Equal(0u,agent.Index00.Read(0),"First member index");Equal(1,group.Members28.Capacity10.Read(0).Index,"Null members grew to one");NavigationCrowdStateContracts.Join25C340(group,agent,b,new Invocation());var second=Buffer(group.Members28);Equal(2,group.Members28.Capacity10.Read(0).Index,"Full one grew to two");Equal(1u,agent.Index00.Read(0),"Duplicate shared member receives latest native index");Same(agent,second.At(0,0).Read(0),"Existing shared member retained");Same(agent,second.At(1,0).Read(0),"Duplicate appended without cloning");Missing(0,delegate{first.At(0,0);},"First member backing released");
   var missing=Agent();missing.Position48.X.Forget();Missing(0x25c385,delegate{NavigationCrowdStateContracts.Join25C340(group,missing,b,new Invocation());},"Position consumed after actual append and growth");var third=Buffer(group.Members28);Equal(3,group.Members28.Capacity10.Read(0).Index,"Full two grows to three");Equal(3,group.Members28.End08.Read(0).Index,"Completed append retained on later math failure");Equal(2u,missing.Index00.Read(0),"Index write retained");Same(missing,third.At(2,0).Read(0),"Same failing member is already published");Same(agent,third.At(0,0).Read(0),"Existing member identity survives second growth");Missing(0,delegate{second.At(0,0);},"Second member backing released");Equal(-2,group.Lower10.X.Read(0),"Bounds remain prior value when first arithmetic fails");Equal(2,group.Upper1C.X.Read(0),"Upper bound remains prior value");agent.RequireLive(0);missing.RequireLive(0);
  });
 }
}
public static class NavigationCrowdGrowthTestProgram {
 public static int Main(){try{NavigationCrowdGrowthTests.Run();Console.WriteLine("PASS "+NavigationCrowdGrowthTests.Scenarios+" scenarios, "+NavigationCrowdGrowthTests.Assertions+" assertions; recovered pointer-vector growth and actual group/member callers in explicit successful managed allocation domain; native allocator/EH and character movement unverified");return 0;}catch(Exception e){Console.Error.WriteLine("FAIL after "+NavigationCrowdGrowthTests.Scenarios+" scenarios, "+NavigationCrowdGrowthTests.Assertions+" assertions: "+e);return 1;}}
}
